import java.io.BufferedInputStream

private const val MOD = 1_000_000_007L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()
    var n = fs.nextLong()
    val k = fs.nextLong().toInt()

    val factors = mutableListOf<Pair<Long, Int>>()

    fun extractFactor(p: Long) {
        if (n % p != 0L) return
        var exponent = 0
        while (n % p == 0L) {
            n /= p
            exponent++
        }
        factors.add(p to exponent)
    }

    extractFactor(2L)
    extractFactor(3L)

    var divisor = 5L
    var step = 2L
    while (divisor <= n / divisor) {
        extractFactor(divisor)
        divisor += step
        step = 6L - step
    }

    if (n > 1L) factors.add(n to 1)

    val inverses = LongArray(51)
    inverses[1] = 1L
    for (i in 2 until inverses.size) {
        inverses[i] =
            (MOD - (MOD / i) * inverses[(MOD % i).toInt()] % MOD) % MOD
    }

    var answer = 1L

    for ((prime, exponent) in factors) {
        var probability = LongArray(exponent + 1)
        probability[exponent] = 1L

        repeat(k) {
            val next = LongArray(exponent + 1)
            var suffix = 0L

            for (e in exponent downTo 0) {
                suffix = (suffix + probability[e] * inverses[e + 1]) % MOD
                next[e] = suffix
            }

            probability = next
        }

        val primeMod = prime % MOD
        var power = 1L
        var expected = 0L

        for (e in 0..exponent) {
            expected = (expected + probability[e] * power) % MOD
            power = power * primeMod % MOD
        }

        answer = answer * expected % MOD
    }

    print(answer)
}

