import java.io.BufferedInputStream

private const val MOD = 1_000_000_007L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32) c = readByte()
        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun expectedPrimePower(prime: Long, exponent: Int, k: Int, inverse: LongArray): Long {
    var current = LongArray(exponent + 1)
    var next = LongArray(exponent + 1)
    current[exponent] = 1L

    var step = 0
    while (step < k) {
        var suffix = 0L
        var i = exponent
        while (i >= 0) {
            suffix += current[i] * inverse[i + 1] % MOD
            if (suffix >= MOD) suffix -= MOD
            next[i] = suffix
            i--
        }

        val temp = current
        current = next
        next = temp
        step++
    }

    val p = prime % MOD
    var power = 1L
    var result = 0L

    for (i in 0..exponent) {
        result += current[i] * power % MOD
        if (result >= MOD) result -= MOD
        power = power * p % MOD
    }

    return result
}

fun main() {
    val scanner = FastScanner()
    var n = scanner.nextLong()
    val k = scanner.nextLong().toInt()

    val factors = ArrayList<Pair<Long, Int>>()

    var count = 0
    while (n % 2L == 0L) {
        n /= 2L
        count++
    }
    if (count > 0) factors.add(2L to count)

    var divisor = 3L
    while (divisor * divisor <= n) {
        count = 0
        while (n % divisor == 0L) {
            n /= divisor
            count++
        }
        if (count > 0) factors.add(divisor to count)
        divisor += 2L
    }

    if (n > 1L) factors.add(n to 1)

    val maxExponent = factors.maxOfOrNull { it.second } ?: 0
    val inverse = LongArray(maxExponent + 2)
    if (inverse.size > 1) inverse[1] = 1L

    for (i in 2 until inverse.size) {
        inverse[i] = (MOD - (MOD / i) * inverse[(MOD % i).toInt()] % MOD) % MOD
    }

    var answer = 1L
    for ((prime, exponent) in factors) {
        answer = answer * expectedPrimePower(prime, exponent, k, inverse) % MOD
    }

    print(answer)
}
